Implement soft delete in `AssetsController` by changing `DeleteConfirmed` to set `StatusId` to **Inactive** instead of removing the row.


```csharp
// GET: Assets
public async Task<IActionResult> Index()
{
    var assets = await _context.Assets
        .AsNoTracking()
        .Include(a => a.AssetType)
        .Include(a => a.AssignedUser)
        .Include(a => a.Location)
        .Include(a => a.Criticality)
        .Include(a => a.Status)
        .Where(a => a.Status == null || a.Status.StatusName != "Inactive") // hide soft-deleted rows
        .OrderBy(a => a.AssetId)
        .ToListAsync();

    return View(assets);
}

// POST: Assets/Delete/5
[HttpPost, ActionName("Delete")]
[ValidateAntiForgeryToken]
public async Task<IActionResult> DeleteConfirmed(string id)
{
    var asset = await _context.Assets.FindAsync(id);
    if (asset == null)
        return RedirectToAction(nameof(Index));

    var inactiveStatusId = await _context.AssetStatuses
        .Where(s => s.StatusName == "Inactive")
        .Select(s => s.StatusId)
        .FirstOrDefaultAsync();

    if (inactiveStatusId == 0)
    {
        ModelState.AddModelError(string.Empty, "Inactive status not found. Add it to AssetStatus first.");
        return RedirectToAction(nameof(Index));
    }

    asset.StatusId = inactiveStatusId;
    asset.UpdatedAt = DateTime.UtcNow;

    await _context.SaveChangesAsync();
    return RedirectToAction(nameof(Index));
}
```


Also make sure your `AssetStatus` table contains a row with `StatusName = 'Inactive'`.  
If it doesn’t, create that status first.

