protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
{
    // Leave empty when Program.cs configures DbContext via DI.
}

Great question. In your current file, the “empty override” is malformed and the old hardcoded SQL line is still active.

Use this exact code.


```csharp
using System;
using System.Collections.Generic;
using AssetRegistry.Models;
using Microsoft.EntityFrameworkCore;

namespace AssetRegistry.Data;

public partial class YourDatabaseContext : DbContext
{
    public YourDatabaseContext()
    {
    }

    public YourDatabaseContext(DbContextOptions<YourDatabaseContext> options)
        : base(options)
    {
    }

    public virtual DbSet<Asset> Assets { get; set; }
    public virtual DbSet<AssetRegistryImport> AssetRegistryImports { get; set; }
    public virtual DbSet<AssetStatus> AssetStatuses { get; set; }
    public virtual DbSet<AssetType> AssetTypes { get; set; }
    public virtual DbSet<BusinessCriticality> BusinessCriticalities { get; set; }
    public virtual DbSet<Location> Locations { get; set; }
    public virtual DbSet<User> Users { get; set; }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Intentionally empty. Connection is configured in Program.cs via DI.
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // keep your existing OnModelCreating content
    }

    partial void OnModelCreatingPartial(ModelBuilder modelBuilder);
}
```


And your `Program.cs` should contain this (yours already does):


```csharp
using AssetRegistry.Data;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
var connectionString = builder.Configuration.GetConnectionString("AssetRegistryContext")
    ?? throw new InvalidOperationException("Connection string 'AssetRegistryContext' not found.");

builder.Services.AddControllersWithViews();

builder.Services.AddDbContext<YourDatabaseContext>(options =>
    options.UseSqlServer(connectionString));

var app = builder.Build();
```


Key fix: remove the old hardcoded `=> optionsBuilder.UseSqlServer("...")` line from `YourDatabaseContext.cs`.

